BEGIN;
CREATE EXTENSION IF NOT EXISTS pgtap WITH SCHEMA extensions;
SELECT extensions.plan(7);
INSERT INTO auth.users(id,aud,role,email) VALUES ('98000000-0000-4000-8000-000000000001','authenticated','authenticated','revoke@example.invalid');
INSERT INTO public.team_members(user_id,role) VALUES ('98000000-0000-4000-8000-000000000001','editor');
INSERT INTO public.influencers(id,name,slug) VALUES ('e6000000-0000-4000-8000-000000000001','Revoke fixture','revoke-fixture');
INSERT INTO public.social_accounts(id,influencer_id,platform,external_id,handle) VALUES ('e7000000-0000-4000-8000-000000000001','e6000000-0000-4000-8000-000000000001','youtube','UCrevoke','fixture');
SELECT extensions.ok(NOT has_function_privilege('authenticated','public.oauth_revoke_begin(uuid,uuid,uuid)','EXECUTE'),'client cannot read token');
SET LOCAL ROLE service_role;
SELECT public.store_social_token('e7000000-0000-4000-8000-000000000001','{"access_token":"fixture","refresh_token":"refresh"}',now()+interval '1 hour');
SELECT set_config('test.revoke',public.oauth_revoke_begin('98000000-0000-4000-8000-000000000001','e7000000-0000-4000-8000-000000000001','e6000000-0000-4000-8000-000000000001')::text,true);
SELECT extensions.is((SELECT status::text FROM public.social_accounts WHERE id='e7000000-0000-4000-8000-000000000001'),'revoked','local work stops before provider call');
SELECT extensions.ok(public.read_social_token('e7000000-0000-4000-8000-000000000001') IS NULL,'revoking token unavailable to workers');
SELECT extensions.throws_ok($$SELECT public.oauth_revoke_begin('98000000-0000-4000-8000-000000000001','e7000000-0000-4000-8000-000000000001','e6000000-0000-4000-8000-000000000001')$$,'55000',NULL,'parallel revoke denied');
SELECT extensions.ok(public.oauth_revoke_finish('e7000000-0000-4000-8000-000000000001',(current_setting('test.revoke')::jsonb->>'nonce')::uuid),'provider success permits cleanup');
SELECT extensions.ok((SELECT token_ref IS NULL FROM public.social_accounts WHERE id='e7000000-0000-4000-8000-000000000001'),'secret reference removed');
SELECT extensions.ok(NOT public.oauth_revoke_finish('e7000000-0000-4000-8000-000000000001',(current_setting('test.revoke')::jsonb->>'nonce')::uuid),'stale cleanup cannot affect new connection');
RESET ROLE;
SELECT * FROM extensions.finish();
ROLLBACK;
